// PAYMENT PRIORITISATION — where THIS month's spare money goes, and in what order.
//
// `payoff` already answers "what does the whole schedule look like at $X a month". This answers the
// question that comes first and gets skipped: how much is genuinely spare, and is the highest rate
// really the right target right now. Three rules, in order, and the middle one is the one people get
// wrong:
//
//  1. MINIMUMS ARE NOT NEGOTIABLE. Nothing paid above a minimum is worth a minimum missed — that is
//     a late fee, a penalty rate on the whole balance, and a credit event that outlasts the month.
//
//  2. A BUFFER BEATS THE RATE, until it exists. Paying a card down to zero liquid and then meeting a
//     car repair puts the repair back on the card at 25% WITH a fee, so the "optimal" payment lost
//     money. Avalanche is optimal given the balance stays paid; a person with no buffer cannot make
//     that promise, and the arithmetic that ignores it is not conservative, it is wrong.
//
//  3. THEN THE RATE — except a 0% promotional balance, which inverts. While the promotion runs it
//     costs nothing to carry and paying it is the worst use of a dollar; when it is about to END it
//     becomes the most urgent thing on the list, because the whole balance is about to start
//     accruing at once. Deprioritised, then jumped to the front, on a date.
//
// AND IF THE RUNWAY DOES NOT HOLD, THERE IS NO SURPLUS. The honest answer is "pay the minimums and
// nothing more", and it is an answer this module will actually give.
import { type Money, money, compare } from "@/features/finance/lib/money";
import type { AccountPosition, Position } from "@/features/finance/lib/position";
import type { Strategy } from "@/features/finance/lib/payoff";
import { type Runway, survivesHorizon } from "@/features/finance/lib/runway";
import { daysBetween } from "@/features/finance/lib/txn";

export type AllocationKind = "minimum" | "buffer" | "extra";

export interface Allocation {
  readonly kind: AllocationKind;
  /** Absent for the buffer, which is not paid to anybody. */
  readonly account?: string;
  readonly label: string;
  readonly amount: Money;
  /** Why this, before the others. */
  readonly reason: string;
}

export interface Priority {
  readonly currency: string;
  readonly strategy: Strategy;
  /** What the runway says is genuinely spare EVERY month, not on a good one. */
  readonly available: Money;
  /** Liquid above the buffer target — a one-off, distinct from the monthly figure. */
  readonly lumpAvailable: Money;
  readonly minimums: Money;
  readonly toBuffer: Money;
  readonly toDebt: Money;
  readonly allocations: readonly Allocation[];
  /** The ONE account to put every spare dollar into. Absent when nothing spare exists. */
  readonly target?: { readonly account: string; readonly institution: string; readonly why: string };
  /** The full order, so the answer after this one is already visible. */
  readonly order: readonly string[];
  readonly warnings: readonly string[];
}

export interface PriorityOptions {
  /** Liquid to hold before any dollar goes above a minimum. */
  readonly bufferTarget: Money;
  readonly strategy?: Strategy;
  /** `YYYY-MM-DD` a 0% promotional rate ends, per account. */
  readonly promoEnds?: Readonly<Record<string, string>>;
  /** How close a promotion's end makes it URGENT rather than cheap. */
  readonly promoUrgencyDays?: number;
  /** Utilisation above which a credit line is called out. */
  readonly utilisationConcern?: number;
}

/** A live 0% promotion makes a balance cost nothing to carry — until it does not. */
type PromoState = "none" | "live" | "expiring";

function promoStateOf(account: string, asOf: string, promoEnds: Record<string, string>, urgencyDays: number): PromoState {
  const ends = promoEnds[account];
  if (!ends || ends <= asOf) return "none";
  return daysBetween(asOf, ends) <= urgencyDays ? "expiring" : "live";
}

/**
 * The order to attack in.
 *
 * EXPIRING promotions first, biggest balance first among them: the whole balance is about to start
 * accruing at once, so the exposure is what matters, not the rate it currently is not charging.
 * Then the ordinary debts by strategy. Then LIVE promotions last, because a dollar paid there buys
 * nothing while the rate is zero.
 */
export function priorityOrder(
  debts: readonly AccountPosition[],
  strategy: Strategy,
  asOf: string,
  promoEnds: Record<string, string> = {},
  urgencyDays = 90,
): AccountPosition[] {
  const state = (a: AccountPosition): PromoState => promoStateOf(a.account, asOf, promoEnds, urgencyDays);
  const rank: Record<PromoState, number> = { expiring: 0, none: 1, live: 2 };

  return [...debts].sort((a, b) => {
    const byPromo = rank[state(a)] - rank[state(b)];
    if (byPromo !== 0) return byPromo;

    if (state(a) === "expiring") {
      const byExposure = compare(b.owed ?? money(0, "USD"), a.owed ?? money(0, "USD"));
      if (byExposure !== 0) return byExposure;
    } else if (strategy === "avalanche") {
      const byRate = (b.apr ?? 0) - (a.apr ?? 0);
      if (byRate !== 0) return byRate;
      const bySize = compare(a.owed ?? money(0, "USD"), b.owed ?? money(0, "USD"));
      if (bySize !== 0) return bySize;
    } else {
      const bySize = compare(a.owed ?? money(0, "USD"), b.owed ?? money(0, "USD"));
      if (bySize !== 0) return bySize;
      const byRate = (b.apr ?? 0) - (a.apr ?? 0);
      if (byRate !== 0) return byRate;
    }
    return a.account.localeCompare(b.account);
  });
}

export function prioritise(position: Position, runway: Runway, opts: PriorityOptions): Priority {
  const {
    bufferTarget,
    strategy = "avalanche",
    promoEnds = {},
    promoUrgencyDays = 90,
    utilisationConcern = 0.9,
  } = opts;
  const currency = position.currency;
  const warnings: string[] = [];

  const debts = position.accounts.filter((a) => a.owed);
  const minimums = debts.reduce((n, a) => n + (a.minimumPayment?.minor ?? 0), 0);

  // WHAT IS GENUINELY SPARE is the WORST month's net under the low band, not a good month's. A
  // monthly commitment made out of the best month is a commitment that fails in the worst one.
  const nets = runway.headline.months.map((m) => m.net.minor);
  const worstNet = nets.length ? Math.min(...nets) : 0;
  let available = Math.max(0, worstNet);

  if (!runway.headline.months.length) {
    warnings.push("there is no runway to read a surplus from, so nothing above the minimums is recommended");
    available = 0;
  } else if (!survivesHorizon(runway.headline)) {
    // THE HONEST AND UNUSUAL ANSWER. Every dollar above a minimum makes the shortfall arrive sooner.
    warnings.push(
      `the money runs out in ${runway.headline.exhaustsIn} on the low income band — there is no surplus, and anything paid above the minimums brings that date forward`,
    );
    available = 0;
  }

  const lumpAvailable = Math.max(0, position.liquid.minor - bufferTarget.minor);
  const bufferShort = Math.max(0, bufferTarget.minor - position.liquid.minor);
  const toBuffer = Math.min(available, bufferShort);
  const toDebt = available - toBuffer;

  if (bufferShort > 0) {
    warnings.push(
      `liquid is ${bufferShort} minor units below the buffer, so that comes first — paying a card to zero and then meeting a repair puts the repair back on the card at its own rate WITH a fee, and the "optimal" payment has lost money`,
    );
  }
  for (const a of position.accounts) {
    if (a.utilisation !== undefined && a.utilisation >= utilisationConcern) {
      warnings.push(
        `${a.institution} is at ${Math.round(a.utilisation * 100)}% of its limit — bringing it under 30% may be worth more than the interest saved elsewhere, which is a judgement this does not make for you`,
      );
    }
  }
  for (const a of debts) {
    if (promoStateOf(a.account, position.asOf, promoEnds, promoUrgencyDays) === "expiring") {
      warnings.push(
        `${a.institution}'s 0% rate ends ${promoEnds[a.account]} — the whole balance starts accruing at once, which is why it is first rather than last`,
      );
    }
  }
  if (!position.complete) {
    warnings.push("the position under this is incomplete, so the surplus above is at best provisional");
  }

  const order = priorityOrder(debts, strategy, position.asOf, promoEnds, promoUrgencyDays);
  const head = order[0];

  const allocations: Allocation[] = debts.map((a) => ({
    kind: "minimum",
    account: a.account,
    label: `${a.institution} minimum`,
    amount: a.minimumPayment ?? money(0, currency),
    reason: "a missed minimum is a late fee, a penalty rate on the whole balance, and a credit event that outlasts the month",
  }));
  if (toBuffer > 0) {
    allocations.push({
      kind: "buffer",
      label: "emergency buffer",
      amount: money(toBuffer, currency),
      reason: "a buffer beats the rate until it exists — without one the next unplanned bill goes back onto the highest-rate card",
    });
  }
  if (toDebt > 0 && head) {
    allocations.push({
      kind: "extra",
      account: head.account,
      label: `${head.institution} — above the minimum`,
      amount: money(toDebt, currency),
      reason: whyTarget(head, strategy, position.asOf, promoEnds, promoUrgencyDays),
    });
  }

  return {
    currency,
    strategy,
    available: money(available, currency),
    lumpAvailable: money(lumpAvailable, currency),
    minimums: money(minimums, currency),
    toBuffer: money(toBuffer, currency),
    toDebt: money(toDebt, currency),
    allocations,
    ...(toDebt > 0 && head
      ? {
          target: {
            account: head.account,
            institution: head.institution,
            why: whyTarget(head, strategy, position.asOf, promoEnds, promoUrgencyDays),
          },
        }
      : {}),
    order: order.map((a) => a.account),
    warnings,
  };
}

function whyTarget(
  a: AccountPosition,
  strategy: Strategy,
  asOf: string,
  promoEnds: Record<string, string>,
  urgencyDays: number,
): string {
  const state = promoStateOf(a.account, asOf, promoEnds, urgencyDays);
  if (state === "expiring") return `its 0% rate ends ${promoEnds[a.account]} and the whole balance begins accruing at once`;
  if (strategy === "avalanche") {
    return a.apr === undefined
      ? "it is the largest debt with no known rate, which is the one most likely to be the expensive one"
      : `it carries the highest known rate at ${Math.round(a.apr * 10000) / 100}%, so every dollar here saves the most interest`;
  }
  return "it is the smallest balance, so it clears soonest and its minimum rolls into the next one";
}

/** Everything the plan asks for this month — minimums, buffer and the extra together. */
export const totalCommitment = (p: Priority): Money =>
  money(p.minimums.minor + p.toBuffer.minor + p.toDebt.minor, p.currency);

