import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import type { AccountPosition, Position } from "@/features/finance/lib/position";
import type { Runway, RunwayMonth, RunwayResult } from "@/features/finance/lib/runway";
import { prioritise, priorityOrder, totalCommitment } from "@/features/finance/lib/priority";

// SYNTHETIC FIXTURES ONLY. No real statement, balance or account number belongs in this repo.
const usd = (major: number): Money => fromMajor(major, "USD");

const debt = (over: Partial<AccountPosition> & { account: string; institution: string }): AccountPosition => ({
  kind: "credit",
  balance: usd(-1000),
  asOf: "2026-06-30",
  rolledForward: 0,
  isDebt: true,
  owed: usd(1000),
  apr: 0.2,
  minimumPayment: usd(35),
  ...over,
});

const CARD_A = debt({ account: "a", institution: "Alpha Card", owed: usd(4000), apr: 0.2499, minimumPayment: usd(90) });
const CARD_B = debt({ account: "b", institution: "Beta Card", owed: usd(800), apr: 0.1499, minimumPayment: usd(25) });
const LOAN = debt({ account: "l", institution: "Gamma Loan", kind: "loan", owed: usd(9000), apr: 0.0699, minimumPayment: usd(210) });

const position = (over: Partial<Position> = {}): Position => ({
  asOf: "2026-06-30",
  currency: "USD",
  accounts: [CARD_A, CARD_B, LOAN],
  netWorth: usd(-11_800),
  liquid: usd(2000),
  totalDebt: usd(13_800),
  dailyInterest: usd(3),
  minimumsDue: usd(325),
  complete: true,
  problems: [],
  provenance: "reconciled · synthetic",
  ...over,
});

const month = (m: string, net: number, closing: number): RunwayMonth => ({
  month: m,
  opening: usd(0),
  income: usd(0),
  obligations: usd(0),
  discretionary: usd(0),
  net: usd(net),
  closing: usd(closing),
  ...(closing < 0 ? { shortfall: usd(-closing) } : {}),
});

const result = (months: RunwayMonth[], over: Partial<RunwayResult> = {}): RunwayResult => ({
  scenario: "low",
  months,
  monthlyGap: usd(0),
  ...(months.some((m) => m.closing.minor < 0)
    ? {
        exhaustsIn: months.find((m) => m.closing.minor < 0)!.month,
        monthsOfCover: months.findIndex((m) => m.closing.minor < 0),
      }
    : {}),
  ...over,
});

const runway = (months: RunwayMonth[]): Runway => {
  const r = result(months);
  return {
    asOf: "2026-06-30",
    currency: "USD",
    startingLiquid: usd(2000),
    low: r,
    expected: r,
    high: r,
    headline: r,
    through: months[months.length - 1]?.month,
    problems: [],
    provenance: "reconciled · synthetic",
  };
};

/** Comfortably in surplus every month, with one leaner one. */
const HEALTHY = runway([
  month("2026-07", 800, 2800),
  month("2026-08", 500, 3300),
  month("2026-09", 900, 4200),
]);

describe("the surplus is the WORST month's, not a good one's", () => {
  it("takes the minimum net across the horizon", () => {
    // A commitment made out of the best month is a commitment that fails in the worst one.
    const p = prioritise(position(), HEALTHY, { bufferTarget: usd(0) });
    expect(p.available.minor).toBe(usd(500).minor);
  });

  it("gives NO surplus at all when the runway does not hold", () => {
    // The honest and unusual answer: every dollar above a minimum brings the shortfall forward.
    const doomed = runway([month("2026-07", -400, 1600), month("2026-08", -900, 700), month("2026-09", -900, -200)]);
    const p = prioritise(position(), doomed, { bufferTarget: usd(0) });
    expect(p.available.minor).toBe(0);
    expect(p.toDebt.minor).toBe(0);
    expect(p.target).toBeUndefined();
    expect(p.allocations.every((a) => a.kind === "minimum")).toBe(true);
    expect(p.warnings.join(" ")).toContain("brings that date forward");
  });

  it("never reports a negative surplus", () => {
    const lean = runway([month("2026-07", -50, 1950)]);
    expect(prioritise(position(), lean, { bufferTarget: usd(0) }).available.minor).toBe(0);
  });

  it("recommends nothing above the minimums with no runway to read", () => {
    const p = prioritise(position(), runway([]), { bufferTarget: usd(0) });
    expect(p.available.minor).toBe(0);
    expect(p.warnings.join(" ")).toContain("no runway to read a surplus from");
  });
});

describe("minimums are not negotiable", () => {
  it("allocates every minimum before anything else, in every scenario", () => {
    const doomed = runway([month("2026-07", -900, -900)]);
    for (const r of [HEALTHY, doomed]) {
      const p = prioritise(position(), r, { bufferTarget: usd(0) });
      const mins = p.allocations.filter((a) => a.kind === "minimum");
      expect(mins).toHaveLength(3);
      expect(p.minimums.minor).toBe(usd(325).minor);
      expect(mins[0].reason).toContain("credit event");
    }
  });

  it("counts the whole commitment, not only the extra", () => {
    const p = prioritise(position(), HEALTHY, { bufferTarget: usd(0) });
    expect(totalCommitment(p).minor).toBe(p.minimums.minor + p.toBuffer.minor + p.toDebt.minor);
    expect(totalCommitment(p).minor).toBe(usd(825).minor);
  });
});

describe("a buffer beats the rate, until it exists", () => {
  it("sends the surplus to the buffer first and says why", () => {
    // Paying a card to zero and then meeting a repair puts the repair back on the card at its own
    // rate WITH a fee, so the "optimal" payment lost money.
    const p = prioritise(position({ liquid: usd(200) }), HEALTHY, { bufferTarget: usd(1000) });
    expect(p.toBuffer.minor).toBe(usd(500).minor);
    expect(p.toDebt.minor).toBe(0);
    expect(p.target).toBeUndefined();
    expect(p.allocations.some((a) => a.kind === "buffer")).toBe(true);
    expect(p.warnings.join(" ")).toContain("has lost money");
  });

  it("splits when the surplus more than covers what the buffer is short", () => {
    const p = prioritise(position({ liquid: usd(800) }), HEALTHY, { bufferTarget: usd(1000) });
    expect(p.toBuffer.minor).toBe(usd(200).minor);
    expect(p.toDebt.minor).toBe(usd(300).minor);
    expect(p.target!.account).toBe("a");
  });

  it("sends everything to the debt once the buffer is met, and says nothing about it", () => {
    const p = prioritise(position({ liquid: usd(2000) }), HEALTHY, { bufferTarget: usd(1000) });
    expect(p.toBuffer.minor).toBe(0);
    expect(p.toDebt.minor).toBe(usd(500).minor);
    expect(p.lumpAvailable.minor).toBe(usd(1000).minor);
    expect(p.warnings.join(" ")).not.toContain("below the buffer");
  });
});

describe("then the rate — except a promotion, which inverts", () => {
  const promo = { b: "2027-06-30" };

  it("puts a LIVE 0% balance last, because a dollar there buys nothing", () => {
    const order = priorityOrder([CARD_A, CARD_B, LOAN], "avalanche", "2026-06-30", promo);
    expect(order.map((a) => a.account)).toEqual(["a", "l", "b"]);
  });

  it("jumps an EXPIRING promotion to the FRONT, ahead of a higher rate", () => {
    // The whole balance is about to start accruing at once, so the exposure is what matters — not
    // the rate it is currently not charging. This is the inversion, and it is the point.
    const order = priorityOrder([CARD_A, CARD_B, LOAN], "avalanche", "2026-06-30", { b: "2026-08-15" });
    expect(order.map((a) => a.account)).toEqual(["b", "a", "l"]);
  });

  it("orders several expiring promotions by EXPOSURE, not by rate", () => {
    const order = priorityOrder([CARD_A, CARD_B, LOAN], "avalanche", "2026-06-30", {
      b: "2026-08-15",
      l: "2026-08-01",
    });
    // Gamma's $9,000 is about to start accruing; Beta's $800 is the smaller problem.
    expect(order.map((a) => a.account)).toEqual(["l", "b", "a"]);
  });

  it("treats an already-expired promotion as no promotion at all", () => {
    const order = priorityOrder([CARD_A, CARD_B, LOAN], "avalanche", "2026-06-30", { b: "2026-01-01" });
    expect(order.map((a) => a.account)).toEqual(["a", "b", "l"]);
  });

  it("warns about the expiry and explains the inversion in the target's reason", () => {
    const p = prioritise(position(), HEALTHY, { bufferTarget: usd(0), promoEnds: { b: "2026-08-15" } });
    expect(p.target!.account).toBe("b");
    expect(p.target!.why).toContain("begins accruing at once");
    expect(p.warnings.join(" ")).toContain("first rather than last");
  });
});

describe("avalanche and snowball", () => {
  it("avalanche takes the highest rate", () => {
    expect(priorityOrder([CARD_A, CARD_B, LOAN], "avalanche", "2026-06-30").map((a) => a.account)).toEqual(["a", "b", "l"]);
    const p = prioritise(position(), HEALTHY, { bufferTarget: usd(0) });
    expect(p.target!.institution).toBe("Alpha Card");
    expect(p.target!.why).toContain("24.99%");
  });

  it("snowball takes the smallest balance", () => {
    expect(priorityOrder([CARD_A, CARD_B, LOAN], "snowball", "2026-06-30").map((a) => a.account)).toEqual(["b", "a", "l"]);
    const p = prioritise(position(), HEALTHY, { bufferTarget: usd(0), strategy: "snowball" });
    expect(p.target!.institution).toBe("Beta Card");
    expect(p.target!.why).toContain("its minimum rolls into the next one");
  });

  it("puts a debt with no known rate where it can do least harm to be wrong", () => {
    const unknown = debt({ account: "u", institution: "Delta", owed: usd(6000), apr: undefined });
    const order = priorityOrder([CARD_A, unknown], "avalanche", "2026-06-30");
    expect(order.map((a) => a.account)).toEqual(["a", "u"]);
    const p = prioritise(position({ accounts: [unknown] }), HEALTHY, { bufferTarget: usd(0) });
    expect(p.target!.why).toContain("no known rate");
  });

  it("shows the whole order, so the answer after this one is already visible", () => {
    expect(prioritise(position(), HEALTHY, { bufferTarget: usd(0) }).order).toEqual(["a", "b", "l"]);
  });
});

describe("what it will not decide for you", () => {
  it("names a near-maxed line without overriding the rate order", () => {
    const maxed = debt({ account: "m", institution: "Epsilon", owed: usd(4800), apr: 0.1, creditLimit: usd(5000), utilisation: 0.96 });
    const p = prioritise(position({ accounts: [CARD_A, maxed] }), HEALTHY, { bufferTarget: usd(0) });
    expect(p.warnings.join(" ")).toContain("96% of its limit");
    expect(p.warnings.join(" ")).toContain("judgement this does not make for you");
    // Alpha still wins on rate; the utilisation point is raised, not acted on.
    expect(p.target!.account).toBe("a");
  });

  it("says the surplus is provisional when the position is incomplete", () => {
    const p = prioritise(position({ complete: false, problems: [] }), HEALTHY, { bufferTarget: usd(0) });
    expect(p.warnings.join(" ")).toContain("at best provisional");
  });

  it("has nothing to allocate with no debts at all", () => {
    const p = prioritise(position({ accounts: [] }), HEALTHY, { bufferTarget: usd(0) });
    expect(p.minimums.minor).toBe(0);
    expect(p.allocations).toEqual([]);
    expect(p.target).toBeUndefined();
    expect(p.order).toEqual([]);
  });
});
